import{_ as a,c as i,o as l,aj as r}from"./chunks/framework.rJ-FfUda.js";const m=JSON.parse('{"title":"Redis设计与实现","description":"","frontmatter":{"title":"Redis设计与实现","hugoSource":"books/computer-science/Redis设计与实现.md","outline":[1,6]},"headers":[],"relativePath":"Books/computer-science/2026-11-17-Redis设计与实现.md","filePath":"Books/computer-science/2026-11-17-Redis设计与实现.md"}'),o={name:"Books/computer-science/2026-11-17-Redis设计与实现.md"};function d(c,e,s,t,n,h){return l(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="第2章-简单动态字符串" tabindex="-1">第2章 简单动态字符串 <a class="header-anchor" href="#第2章-简单动态字符串" aria-label="Permalink to “第2章 简单动态字符串”">​</a></h2><h2 id="第3章-链表" tabindex="-1">第3章 链表 <a class="header-anchor" href="#第3章-链表" aria-label="Permalink to “第3章 链表”">​</a></h2><h2 id="第4章-字典" tabindex="-1">第4章 字典 <a class="header-anchor" href="#第4章-字典" aria-label="Permalink to “第4章 字典”">​</a></h2><h2 id="第5章-跳跃表" tabindex="-1">第5章 跳跃表 <a class="header-anchor" href="#第5章-跳跃表" aria-label="Permalink to “第5章 跳跃表”">​</a></h2><h2 id="第6章-整数集合" tabindex="-1">第6章 整数集合 <a class="header-anchor" href="#第6章-整数集合" aria-label="Permalink to “第6章 整数集合”">​</a></h2><h2 id="第7章-压缩列表" tabindex="-1">第7章 压缩列表 <a class="header-anchor" href="#第7章-压缩列表" aria-label="Permalink to “第7章 压缩列表”">​</a></h2><h2 id="第8章-对象" tabindex="-1">第8章 对象 <a class="header-anchor" href="#第8章-对象" aria-label="Permalink to “第8章 对象”">​</a></h2><ul><li>Redis使用对象来表示数据库中的键和值，每次当我们在Redis的数据库中新创建一个键值对时，我们至少会创建两个对象，一个对象用作键值对的键（键对象），另一个对象用作键值对的值（值对象）</li><li>对象的类型 <ul><li>字符串对象 <code>REDIS_STRING</code></li><li>列表对象 <code>REDIS_LIST</code></li><li>哈希对象 <code>REDIS_HASH</code></li><li>集合对象 <code>REDIS_SET</code></li><li>有序集合对象 <code>REDIS_ZSET</code></li></ul></li><li>对于Redis数据库保存的键值对来说，键总是一个字符串对象，而值则可以是字符串对象、列表对象、哈希对象、集合对象或者有序集合对象的其中一种 <ul><li>当我们称呼一个数据库键为“字符串键”时，我们指的是“这个数据库键所对应的值为字符串对象”</li><li>当我们称呼一个键为“列表键”时，我们指的是“这个数据库键所对应的值为列表对象”</li></ul></li><li>TYPE命令的实现方式也与此类似，当我们对一个数据库键执行TYPE命令时，命令返回的结果为数据库键对应的值对象的类型，而不是键对象的类型 <ul><li>因为键的类型始终为字符串</li></ul></li></ul>',8)])])}const u=a(o,[["render",d]]);export{m as __pageData,u as default};
